#include <string>

inline std::string event_log;

struct Tracker {
    std::string name;
    explicit Tracker(std::string n) : name(std::move(n)) { event_log += "+" + name + " "; }
    ~Tracker() { event_log += "-" + name + " "; }
};

void run_scenario() {
    Tracker a("a");
    {
        Tracker b("b");
    }
    {
        Tracker c("c");
    }
}
